export type TranslationKey = keyof typeof translations.tr;
export type Locale = keyof typeof translations;

function interpolate(template: string, params?: Record<string, string | number>): string {
  if (!params) return template;
  return template.replace(/\{(\w+)\}/g, (m, name) => (name in params ? String(params[name]) : m));
}

/**
 * Look up a UI string. Falls back target -> en -> tr -> key, so a partial
 * dictionary is safe. Use this directly in non-hook code (utils, functions);
 * inside components prefer `t` from `useAppTheme()`.
 */
export function translate(
  key: TranslationKey,
  locale: string,
  params?: Record<string, string | number>
): string {
  const dict = (translations as Record<string, Record<string, string>>)[locale];
  const raw = dict?.[key] || translations.en[key] || translations.tr[key] || key;
  return interpolate(raw, params);
}
